<?php
declare(strict_types=1);
namespace App\BusinessModules\Core\Reporting\Application\Subscriptions;
use App\BusinessModules\Core\Reporting\Application\Access\ReportExecutionContextFactory; use App\BusinessModules\Core\Reporting\Application\Contracts\Execution\CurrentReportScopeAuthorizer; use App\BusinessModules\Core\Reporting\Application\Execution\CurrentReportAuthorizationTarget; use App\BusinessModules\Core\Reporting\Domain\DTO\{ReportExecutionContext,ReportSubscription}; use App\BusinessModules\Core\Reporting\Domain\Enums\ReportOperation; use App\BusinessModules\Core\Reporting\Domain\Contracts\ReportDefinitionRegistry; use DateTimeZone;
final readonly class ReportSubscriptionExecutionContextFactory { public function __construct(private CurrentReportScopeAuthorizer $authorizer,private ReportExecutionContextFactory $contexts,private ReportDefinitionRegistry $definitions) {} public function forSubscription(ReportSubscription $subscription,ReportOperation $operation): ReportExecutionContext { $published=$this->definitions->published($subscription->reportCode); $definition=$published->payload(); if (!hash_equals($subscription->definitionHash->value,$definition->definitionHash->value) || $subscription->contractVersion!==$definition->contractVersion) throw new \RuntimeException('report_subscription_definition_changed'); $authorization=$this->authorizer->authorizeForOrganization($subscription->ownerId,$subscription->organizationId,new DateTimeZone('UTC'),new CurrentReportAuthorizationTarget($definition,$operation,null)); return $this->contexts->fromCurrentAuthorization($authorization); } }
